import React from 'react';
import '../styles/theme.css';

export default function Reports() {
  const reportCategories = [
    { title: 'Purchase Reports', icon: '🌾' },
    { title: 'Sales Reports', icon: '📦' },
    { title: 'Stock Reports', icon: '🏢' },
    { title: 'Outstanding Report', icon: '💰' }
  ];

  return (
    <div style={{ padding: '20px', maxWidth: '480px', margin: '0 auto', fontFamily: 'Segoe UI, sans-serif' }}>
      
      {/* Header */}
      <h2 style={{ color: '#1B4D3E', marginBottom: '20px' }}>Reports</h2>

      {/* Estimated Net Profit Card */}
      <div style={{ background: '#1B4D3E', color: '#FFF', padding: '20px', borderRadius: '12px', marginBottom: '25px', boxShadow: '0 4px 10px rgba(0,0,0,0.05)' }}>
        <div style={{ fontSize: '13px', opacity: 0.8, marginBottom: '6px' }}>Estimated net profit — Aug 2026</div>
        <div style={{ fontSize: '28px', fontWeight: 'bold', marginBottom: '15px' }}>₹ 8,25,000</div>
        
        <div style={{ display: 'flex', justifyContent: 'space-between', borderTop: '1px solid rgba(255,255,255,0.2)', paddingTop: '12px', fontSize: '12px' }}>
          <span>Sales ₹98.5L</span>
          <span>Purchase ₹85L</span>
          <span>Expenses ₹5.25L</span>
        </div>
      </div>

      {/* Report Categories */}
      <h3 style={{ fontSize: '16px', color: '#1B4D3E', marginBottom: '12px' }}>Report categories</h3>

      {reportCategories.map((item, index) => (
        <div key={index} style={reportCardStyle}>
          <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
            <div style={{ background: '#F4F7F6', width: '38px', height: '38px', borderRadius: '8px', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '18px' }}>
              {item.icon}
            </div>
            <span style={{ fontWeight: '600', color: '#333', fontSize: '15px' }}>{item.title}</span>
          </div>
          <span style={{ color: '#888', fontWeight: 'bold' }}>›</span>
        </div>
      ))}

    </div>
  );
}

const reportCardStyle = {
  background: '#FFF',
  padding: '16px',
  borderRadius: '12px',
  border: '1px solid #EAE5D9',
  display: 'flex',
  justifyContent: 'space-between',
  alignItems: 'center',
  marginBottom: '12px',
  boxShadow: '0 2px 5px rgba(0,0,0,0.03)',
  cursor: 'pointer'
};
